<?php
$title='Add Provider';
require __DIR__.'/../includes/header.php';
require_login('admin');
require __DIR__.'/../config/database.php';
require_once __DIR__.'/../includes/functions.php';
require_once __DIR__.'/../includes/location_bootstrap.php';
ensure_sri_lanka_locations($pdo);
$cats=$pdo->query("SELECT id,name FROM service_categories WHERE status='active' ORDER BY id")->fetchAll();
$vehicleTypes=$pdo->query("SELECT id,name FROM vehicle_types WHERE status='active' ORDER BY id")->fetchAll();
$provinces=$pdo->query('SELECT id,name FROM provinces ORDER BY id')->fetchAll();
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
  try{
    $name=trim($_POST['owner_name']??''); $email=trim($_POST['email']??''); $phone=trim($_POST['phone']??''); $password=$_POST['password']??'';
    $business=trim($_POST['business_name']??''); $whatsapp=trim($_POST['whatsapp']??''); $address=trim($_POST['address']??''); $maps=trim($_POST['google_maps_link']??'');
    $province=(int)($_POST['province_id']??0); $district=(int)($_POST['district_id']??0); $city=(int)($_POST['city_id']??0);
    $lat=($_POST['latitude']??'')!==''?(float)$_POST['latitude']:null; $lng=($_POST['longitude']??'')!==''?(float)$_POST['longitude']:null; $acc=($_POST['location_accuracy']??'')!==''?(float)$_POST['location_accuracy']:null;
    $categoryIds=array_values(array_unique(array_filter(array_map('intval',(array)($_POST['category_ids']??[])))));
    $vehicleIds=array_values(array_unique(array_filter(array_map('intval',(array)($_POST['vehicle_type_ids']??[])))));
    if($maps!==''){[$mlat,$mlng]=extract_google_maps_coordinates($maps);if($mlat!==null&&$mlng!==null){$lat=$mlat;$lng=$mlng;$acc=null;}}
    if(!$business||!$name||!$email||!$password) throw new RuntimeException('Business name, contact person, email and password are required.');
    if(strlen($password)<6) throw new RuntimeException('Provider password must contain at least 6 characters.');
    if(!$categoryIds) throw new RuntimeException('Select at least one service category.');
    if(!$vehicleIds) throw new RuntimeException('Select at least one vehicle type.');
    if(!$province||!$district||!$city) throw new RuntimeException('Select the service province, district and town/area.');
    if($lat===null||$lng===null) throw new RuntimeException('Set the service-station location using the map, current location, or a Google Maps link.');
    $q=$pdo->prepare('SELECT id FROM districts WHERE id=? AND province_id=?');$q->execute([$district,$province]);if(!$q->fetchColumn())throw new RuntimeException('Invalid district for selected province.');
    ensure_sri_lanka_cities($pdo,$district); $q=$pdo->prepare('SELECT id FROM cities WHERE id=? AND district_id=?');$q->execute([$city,$district]);if(!$q->fetchColumn())throw new RuntimeException('Invalid town/area for selected district.');
    $pdo->beginTransaction();
    $st=$pdo->prepare("INSERT INTO users(name,email,phone,password_hash,role,status) VALUES(?,?,?,?, 'provider','active')");$st->execute([$name,$email,$phone,password_hash($password,PASSWORD_DEFAULT)]);$uid=(int)$pdo->lastInsertId();
    $st=$pdo->prepare("INSERT INTO providers(user_id,business_name,owner_name,whatsapp,address,google_maps_link,latitude,longitude,location_accuracy,district_id,city_id,description,emergency_24h,approval_status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,'approved')");
    $st->execute([$uid,$business,$name,$whatsapp,$address,$maps!==''?$maps:null,$lat,$lng,$acc,$district,$city,trim($_POST['description']??''),isset($_POST['emergency'])?1:0]);$pid=(int)$pdo->lastInsertId();
    $st=$pdo->prepare('INSERT INTO provider_services(provider_id,category_id) VALUES(?,?)');foreach($categoryIds as $id)$st->execute([$pid,$id]);
    $st=$pdo->prepare('INSERT INTO provider_vehicle_types(provider_id,vehicle_type_id) VALUES(?,?)');foreach($vehicleIds as $id)$st->execute([$pid,$id]);
    $pdo->prepare('INSERT INTO provider_availability(provider_id,available) VALUES(?,1)')->execute([$pid]);
    $pdo->commit(); redirect(BASE_URL.'admin/providers.php?created=1');
  }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'Unable to create provider. The email may already be in use.';}
}
$oldCats=array_map('intval',(array)($_POST['category_ids']??[]));$oldVehicles=array_map('intval',(array)($_POST['vehicle_type_ids']??[]));
?>
<section class="section-pad"><div class="container"><div class="col-lg-10 mx-auto card border-0 shadow-sm p-4 rounded-4"><div class="d-flex justify-content-between align-items-center mb-2"><div><h2 class="fw-bold mb-1">Add Service Provider</h2><p class="text-muted mb-0">Create and approve provider accounts from the administrator portal.</p></div><a href="providers.php" class="btn btn-outline-secondary">Back</a></div>
